css:
:root {
  --bg-primary: #fafafa;
  --bg-card: #ffffff;
  --text-primary: #2c2c2c;
  --text-secondary: #777777;
  --accent-primary: #555555;
  --accent-border: #e8e8e8;
}

.cs-card {
  border: 1px solid var(--accent-border);
  border-radius: 4px;
  padding: 20px;
  margin: 8px 0;
}

.cs-btn {
  border-radius: 3px;
  font-weight: 400;
}
